// Shared editorial source for the Academy and Software Atlas. Readiness is advice, not certification.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const learningPlanVersion='2026-11-05';
export const languagePriorities={python:'Start now · main coding focus',cpp:'Next · after comfortable Python basics',matlab:'Coursework / controls · timing can move earlier',c:'Embedded projects · separate from C++',bash:'Start now · small supporting habit'};
export const pythonChecks=[
 ['program','I can turn a short problem description into a small program using functions, conditions, loops, lists or dictionaries.'],
 ['data','I can read a CSV file, handle an invalid or missing value deliberately, and make a labeled plot using documentation.'],
 ['debug','I can read a traceback, inspect values, isolate a bug, and explain the fix.'],
 ['verify','I can check a normal case and a boundary or invalid case against an expected result.'],
 ['transfer','I have completed two small programs, can explain their important lines, and can change a requirement without copying a full solution.']
];
export const stages=[
 {id:'now',number:'01',label:'START NOW',title:'One CAD package + Python',level:'Beginner → comfortable fundamentals',body:'These are your two substantial learning tracks. CAD develops physical design; Python develops programming and analysis. Keep math and physics coursework central.',ready:'Start immediately. Use arithmetic, units, measurements, and simple geometry; advanced mathematics is not an entry requirement.',proof:'Make a dimensioned part or small assembly and check its fit. Write a calculation or sensor-log program and verify its outputs.',next:'Add C++ when the Python checkpoint above is repeatable. CAD does not have to be finished first.',links:[['Python lessons','/coding_python#library'],['Choose one CAD tool','/softwares/#catalog?family=CAD%20%26%20manufacturing']]},
 {id:'cpp',number:'02',label:'NEXT MAJOR CODING TRACK',title:'Add C++ alongside Python',level:'Comfortable beginner Python is enough',body:'You do not need expert Python, every library, advanced classes, or the entire Academy completed. For autonomy and flight-software interests, C++ is the next substantial language investment.',ready:'You can plan, write, debug, check, and modify small Python programs with references. Use the five practical checks above.',proof:'Rebuild a familiar calculation in C++; compile it, fix errors, write functions, use standard containers, and test input boundaries.',next:'Keep Python active for analysis. Deepen C++ through a robot or simulation component. Learning C first is not required.',links:[['First C++ lesson','/coding_Cplusplus#lesson/cpp-01'],['Python practice','/coding_python#practice']]},
 {id:'course',number:'03',label:'COURSEWORK CAN MOVE THIS EARLIER',title:'MATLAB, then Simulink as needed',level:'Basic programming → models you can explain',body:'MATLAB can overlap Python or precede C++ when a class requires it. For controls and GNC, it can become a major skill alongside Python and C++.',ready:'For MATLAB: understand variables, functions, arrays, and the mathematics of the problem. For Simulink: understand the simple system, its inputs, outputs, and changing state.',proof:'Reproduce a calculation or plot in MATLAB. Model a simple dynamic system in Simulink and compare it with an equation or measured response.',next:'Learn feedback, numerical methods, and model validation with coursework. Explore blocks early; defer complex control design until the relevant math develops.',links:[['MATLAB pathway','/coding_matlab#library'],['Controls tools','/softwares/#catalog?family=Computing%20%26%20controls']]},
 {id:'connect',number:'04',label:'ONE PROJECT EXTENSION AT A TIME',title:'Connect code, sensors, and simulation',level:'Small independent programs → integrated projects',body:'Choose a robotics, camera, or embedded project. ROS 2, OpenCV, simulators, and microcontrollers are branches you can begin separately—not a checklist to start together.',ready:'For ROS 2: small Python programs plus basic terminal use. For C or embedded work: basic programming and a concrete board/sensor task. For simulation: a simple model whose behavior you can check.',proof:'A robot component exchanges data; a camera measurement has a known error; or a sensor logger handles missing readings. Explain at least one failure and recovery.',next:'Use one primary robotics simulator initially. C++ depth grows alongside ROS 2; C becomes a focused track when firmware calls for it.',links:[['Robotics tools','/softwares/#catalog?family=Robotics%20%26%20autonomy'],['C pathway','/coding_C#library']]},
 {id:'specialize',number:'05',label:'DEEPEN WHEN THE PHYSICS AND PROJECT ALIGN',title:'Choose a specialty workflow',level:'Working foundations → defensible engineering',body:'Structures, thermal, propulsion, spacecraft dynamics, and autonomy need different combinations. Develop depth in the branch you actually enjoy while keeping adjacent tools familiar.',ready:'You can explain the physical assumptions, identify inputs and units, estimate a simple answer, and define a way to check the result.',proof:'Compare a model with a hand calculation, benchmark, or experiment. Investigate sensitivity, numerical settings, and disagreement.',next:'Add a second package only for a capability, course, team, or employer need. Professional expertise continues after the first useful project.',links:[['Explore specializations','/softwares/#paths'],['Project studio','/coding_learning_main#projects']]}
];
export const softwareGates=[
 ['CAD: FreeCAD / SOLIDWORKS / Fusion / Onshape','Start now; choose one.','Comfortable means independently creating constrained parts, a small assembly, and a drawing, then checking dimensions or fit. Try another CAD package when a team needs it or the first workflow is dependable.'],
 ['Bash / Linux, Git, editor, debugger, testing','Small supporting habits from the start.','Learn files, environments, running programs, breakpoints, tests, and version recovery as needed. You do not need a long standalone course in each tool. CMake joins your first multi-file C++ project.'],
 ['Isaac Sim / Gazebo / MuJoCo','Guided exploration can start now; choose one primary simulator for project work.','Go deeper when you can change a simple model or script, inspect state or sensor output, and explain the effect. Isaac Sim is a reasonable first choice given your existing exploration; Gazebo can follow a ROS project that needs it.'],
 ['ROS 2 + Nav2 or MoveIt 2','ROS 2 after small programs + terminal basics; Python is sufficient to begin.','Before Nav2 or MoveIt 2, understand nodes, topics, launch files, coordinate frames, and basic debugging. Choose Nav2 for mobile robots or MoveIt 2 for arms. Do not wait for expert C++.'],
 ['OpenCV, then PyTorch if needed','OpenCV when your project needs images; PyTorch when it needs learned models.','Start with arrays, image coordinates, and simple measurements. Before substantial ML, understand the task, a baseline, train/test separation, and how you will measure errors.'],
 ['Arduino / PlatformIO, C, KiCad / LTspice, FreeRTOS','A sensor/board project can begin after programming basics.','Start with a working sensor logger. Add circuit design when you can reason about the circuit; add FreeRTOS when multiple timed tasks justify it. Arduino sketches commonly use C++, so using Arduino is not the same as studying C.'],
 ['Ansys Mechanical / other structural solvers','After basic CAD, statics, and relevant mechanics of materials.','Explain loads, supports, material assumptions, and stress/deflection. Check a simple case before trusting a complex mesh. Learn one FEA workflow first.'],
 ['Thermal Desktop / Fluent / other thermal and fluid tools','When a thermal or fluid project and the relevant physics align.','Start with energy balances and a simple temperature model. Thermal networks need heat-transfer reasoning; CFD additionally needs flow physics, boundary conditions, meshing, and convergence checks.'],
 ['Basilisk / GMAT / STK / SPICE','Choose the tool for the question: spacecraft dynamics or mission geometry.','For Basilisk, build Python plus dynamics, frames, and controls. For GMAT, build orbital mechanics and propagation understanding. A simple guided example can come earlier; defend assumptions before independent analysis.'],
 ['OpenVSP / aerodynamic tools / Cantera / NASA CEA','When aircraft or propulsion projects become a focus.','Geometry exploration can begin early. Quantitative aerodynamic or thermochemical claims need the relevant fluids, thermodynamics, chemistry, and model limitations.'],
 ['LabVIEW / requirements tools / industrial CAD alternatives','When a lab, team, course, or project needs that workflow.','Learn the underlying measurement, requirements, or design skill first. A product name alone does not create another major study obligation.'],
 ['Blender / ParaView / writing and reference tools','Use when you need the output; creative exploration is welcome now.','Make a clear render, animation, scientific plot, or report. These can support your projects without displacing your main CAD and programming practice.']
];
export function toolRole(t){
 const id=t.id;
 if(id==='python')return {label:'Start now · main track',when:'Python is your main coding focus. Add C++ after comfortable fundamentals, not expert mastery.'};
 if(['freecad','solidworks','autodesk-fusion','onshape'].includes(id))return {label:'Start now · choose one CAD',when:'Choose one primary CAD package. Alternatives are not extra starting requirements.'};
 if(id==='cpp')return {label:'Next · after Python checkpoint',when:'Start after you can independently write, debug, test, and modify small Python programs. Continue Python alongside it.'};
 if(id==='c')return {label:'When firmware needs it',when:'Learn C through a concrete embedded project after programming basics. C is not a prerequisite for C++.'};
 if(id==='matlab'||id==='simulink')return {label:'Coursework / controls',when:'MATLAB follows coursework and can come before C++. Simulink follows a simple system model and relevant dynamics.'};
 if(['numpy','scipy','pandas','matplotlib','sympy'].includes(id))return {label:'Part of Python practice',when:'Learn this inside a Python project when the data or mathematics needs it; it is not a separate starting course.'};
 if(['git','github','vscode','linux','jupyter','excel','excel-sheets','cmake','gdb','pytest','docker','zotero','latex'].includes(id)||/Excel|Google Sheets/.test(t.name))return {label:'Supporting proficiency',when:'Learn enough for your current work. Debugging, tests, and reviewing changes matter; this is not an equal-sized mastery track.'};
 if(id==='ros-2')return {label:'After code + terminal basics',when:'Begin with Python and terminal basics. Add C++ depth alongside projects; expert C++ is not required first.'};
 if(/Isaac|Gazebo|MuJoCo/.test(t.name))return {label:'Project simulator · choose one',when:'Explore early. Go deeper with a simple model or script you can modify and check. Add alternatives when useful.'};
 if(id==='opencv')return {label:'When your project uses cameras',when:'Start after Python fundamentals and basic arrays. Measure the quality of image-processing results.'};
 return {label:t.priority==='explore'?'Explore when useful':'Specialty / project depth',when:'Use the Focus & readiness guide to match this tool to a concrete project and its prerequisites. Calendar dates are context, not a waiting rule.'};
}
export function focusSummary(context='academy',language='python'){
 const choice=languagePriorities[language];
 return `<section class="lp-summary"><div><span class="lp-eyebrow">YOUR LEARNING ORDER</span><h2>Python + one CAD now.<br>C++ after comfortable basics.</h2><p>No need to wait for expert Python. MATLAB follows coursework; C follows embedded projects; Bash is a small habit from the start.</p>${context==='academy'&&choice&&language!=='python'?`<p class="lp-choice"><strong>Your selected pathway:</strong> ${esc(({cpp:"C++",matlab:"MATLAB",c:"C",bash:"Bash / Linux"})[language])} — ${esc(choice)}. A selection is not a readiness assessment.</p>`:''}</div><a class="lp-button" href="#focus">Focus & readiness →</a></section>`;
}
export function readinessMessage(values){const n=pythonChecks.filter(([id])=>values[id]===true).length;return n===pythonChecks.length?'Ready to try C++ alongside Python. Start small and keep practicing Python; this is a self-assessment, not a certification.':`${n} of ${pythonChecks.length} checks. Keep Python as your main coding track and practice the unchecked skills. A short C++ preview is fine; you do not need a second full course yet.`;}
export function focusView(context='academy'){
 return `<div class="lp-page"><header class="lp-hero"><span class="lp-eyebrow">ONE PLAN · ACADEMY + SOFTWARE ATLAS</span><h1>What to learn next.<br><em>And when you’re ready.</em></h1><p>Start with Python and one CAD package. Add tools when you can use the previous foundations independently on a small task. Expertise grows while you build.</p><div class="lp-pills"><span>Now: Python + CAD</span><span>Next: C++ after basics</span><span>Alongside: Bash / Linux</span></div></header>
 <section class="lp-answer"><h2>Do I need intermediate or expert Python first?</h2><p><strong>No. Aim for a comfortable beginner who can finish small programs independently.</strong> “Intermediate” is too vague to be a useful gate. You can look up syntax, read documentation, and ask for hints. You should be able to explain, change, and check the final program without depending on a generated solution you do not understand.</p><p>Two small projects are a useful recommended checkpoint—not a universal hiring standard. Finishing every lesson, mastering every library, or waiting a fixed number of months is unnecessary.</p></section>
 <section class="lp-check"><div><span class="lp-eyebrow">PYTHON → C++ CHECKPOINT</span><h2>Can you do these reliably?</h2><p>Check against actual work. These answers are temporary and are not saved or used to change your lesson progress.</p></div><fieldset><legend>Python readiness self-check</legend>${pythonChecks.map(([id,text])=>`<label><input type="checkbox" data-lp-check="${id}"><span>${esc(text)}</span></label>`).join('')}</fieldset><p class="lp-result" role="status" aria-live="polite">${readinessMessage({})}</p><a class="lp-button" href="/coding_Cplusplus#lesson/cpp-01">Preview the first C++ lesson ↗</a></section>
 <section aria-label="Learning sequence"><div class="lp-section-title"><span class="lp-eyebrow">ORDER OF MAJOR INVESTMENT</span><h2>A sequence with room for coursework.</h2><p>Stages can overlap. MATLAB can move earlier for a course, Bash starts immediately, and a specific embedded project can bring C forward.</p></div><div class="lp-stages">${stages.map(s=>`<article class="lp-stage" id="lp-${s.id}"><span class="lp-number">${s.number}</span><div><span class="lp-eyebrow">${s.label}</span><h3>${s.title}</h3><p class="lp-level">${s.level}</p><p>${s.body}</p><dl><dt>Start when</dt><dd>${s.ready}</dd><dt>Evidence to keep</dt><dd>${s.proof}</dd><dt>Then</dt><dd>${s.next}</dd></dl><div class="lp-links">${s.links.map(([t,url])=>`<a href="${url}">${t} ↗</a>`).join('')}</div></div></article>`).join('')}</div></section>
 <section class="lp-rhythm"><span class="lp-eyebrow">HOW TO DIVIDE YOUR ATTENTION</span><h2>One main coding track. Keep the foundations active.</h2><div class="lp-columns"><div><h3>Before the Python checkpoint</h3><p>Most dedicated coding sessions: Python. Keep CAD as your other substantial engineering practice. Use a little Bash/Linux inside those sessions. Leave a smaller exploration slot for Isaac Sim, a board, or another curiosity.</p></div><div><h3>After the Python checkpoint</h3><p>Example coding week: three Python sessions and two short C++ sessions. Adjust to coursework and available time. Rebuild a familiar Python task in C++ so only the language is new.</p></div><div><h3>If the overlap becomes confusing</h3><p>Make the C++ task smaller and keep Python as the anchor. Resume a second recurring track when you can explain both versions. A class or active project may temporarily become the main focus.</p></div></div></section>
 <section><div class="lp-section-title"><span class="lp-eyebrow">THE REST OF YOUR TOOLKIT</span><h2>When to add each software family.</h2><p>These are branches, not twelve more courses to begin at once. Guided exploration can come before independent engineering use.</p></div><div class="lp-gates">${softwareGates.map(([name,start,gate])=>`<details><summary>${name}</summary><p><strong>When:</strong> ${start}</p><p><strong>Readiness / useful depth:</strong> ${gate}</p></details>`).join('')}</div></section>
 <section class="lp-answer"><h2>What “knowing your way around” should mean.</h2><div class="lp-columns"><div><h3>Explore</h3><p>Explain the purpose, run a guided example, and know when the tool might help. This is a useful goal across the wider catalog.</p></div><div><h3>Working independently</h3><p>Complete a small task, change it, troubleshoot common problems, and check the output. This is usually enough to begin the next connected tool.</p></div><div><h3>Deep / expert</h3><p>Handle unfamiliar problems, justify assumptions and trade-offs, validate results, and review others’ work. Develop this over years in selected specialties.</p></div></div></section>
 <footer class="lp-footer"><p>Readiness beats calendar dates. Suggested years in the Atlas are planning context; coursework, project needs, and demonstrated skills determine the next step. Updated November 5, 2026.</p><p>Recommendations for your broad aerospace path, not prerequisites imposed by every employer. <a href="https://job-boards.greenhouse.io/andurilindustries/jobs/5062357007">Example simulation role</a> · <a href="https://github.com/ros2/rclpy">ROS 2 Python interface</a></p><a class="lp-button" href="${context==='academy'?'/softwares/#focus':'/coding_learning_main#focus'}">${context==='academy'?'Open this plan in the Software Atlas':'Open this plan in the Academy'} ↗</a></footer></div>`;
}
export function bindFocusView(root){const page=root.querySelector('.lp-page');if(!page)return;page.addEventListener('change',e=>{if(!e.target.matches('[data-lp-check]'))return;const values=Object.fromEntries([...page.querySelectorAll('[data-lp-check]')].map(el=>[el.dataset.lpCheck,el.checked]));page.querySelector('.lp-result').textContent=readinessMessage(values);});}
